namespace PrintGeometry { namespace {
ManufacturingMeshResult fail(ManufacturingMeshError e,const QString&m){ManufacturingMeshResult r;r.error=e;r.diagnostic=m;return r;}
int order(SemanticRole r){return r==SemanticRole::PrimaryBody?0:r==SemanticRole::SubtractivePassage?1:r==SemanticRole::AdditiveAttachment?2:3;}
QString operandIdentity(const SemanticOperand&o){return o.sourceFiles.join('|');}
QString orientationName(FitPrintedOrientation o){return o==FitPrintedOrientation::FeatureAxisPerpendicularToBuildPlate?"feature-axis-perpendicular-to-build-plate":o==FitPrintedOrientation::FeatureAxisParallelToBuildPlate?"feature-axis-parallel-to-build-plate":"unsupported";}
bool matches(const FitProfileCorrection&c,const QString&family,const QString&role,const QString&semantics,const QString&orientation){return c.featureFamily==family&&c.featureRole==role&&c.printedOrientation==orientation&&c.units==QStringLiteral("millimetres")&&c.semantics==semantics;}
bool correctionApplies(const FunctionalFeature&feature,const ManufacturingMeshCorrections&corrections){return (feature.family==FunctionalInterfaceFamily::RoundTechnicPassage&&feature.role==FunctionalInterfaceRole::Female&&corrections.femaleDiameter&&feature.evidenceContract==corrections.femaleDiameter->semanticContractVersion)||(feature.family==FunctionalInterfaceFamily::StandardStud&&feature.role==FunctionalInterfaceRole::Male&&((corrections.studDiameter&&feature.evidenceContract==corrections.studDiameter->semanticContractVersion)||(corrections.studHeight&&feature.evidenceContract==corrections.studHeight->semanticContractVersion)))||(feature.family==FunctionalInterfaceFamily::StudReceivingClutch&&feature.role==FunctionalInterfaceRole::Female&&corrections.receivingTubeDiameter&&feature.evidenceContract==corrections.receivingTubeDiameter->semanticContractVersion);}
QString axisName(const Point&axis){return QStringLiteral("(%1, %2, %3)").arg(axis.x,0,'g',4).arg(axis.y,0,'g',4).arg(axis.z,0,'g',4);}
}

ManufacturingMeshService::ManufacturingMeshService(BooleanServiceFactory f,SemanticBuilderFunction b):m_factory(f?std::move(f):[]{return std::make_unique<McutMeshBooleanService>();}),m_builder(std::move(b)){}

ManufacturingMeshCorrections ManufacturingMeshService::compatibleCorrections(const FitProfile&profile,FitPrintedOrientation orientation,QString*reason)
{
    ManufacturingMeshCorrections result;QString compatibility;if(!FitCalibrationLibrary::profileCompatibility(profile,&compatibility)){if(reason)*reason=compatibility;return result;}const QString printedOrientation=orientationName(orientation);const FitProfileCorrection*heightCandidate=nullptr;
    for(const auto&correction:profile.corrections){if(matches(correction,"RoundTechnicPassage","female","female-diameter-clearance",printedOrientation))result.femaleDiameter=&correction;else if(matches(correction,"StandardStud","male","male-stud-diameter",printedOrientation))result.studDiameter=&correction;else if(matches(correction,"StandardStud","male","male-stud-height",printedOrientation))heightCandidate=&correction;else if(matches(correction,"StudReceivingClutch","female","female-stud-receiver-tube-od",printedOrientation))result.receivingTubeDiameter=&correction;}
    if(heightCandidate){if(!heightCandidate->hasRequiredDiameterCorrection)result.studHeightDiagnostic=QStringLiteral("The Verified Stud Height correction does not record its required Stud OD context and was not applied.");else if(!result.studDiameter)result.studHeightDiagnostic=QStringLiteral("The Verified Stud Height correction requires its matching Verified Stud OD correction and was not applied.");else if(std::abs(result.studDiameter->valueMillimetres-heightCandidate->requiredDiameterCorrectionMillimetres)>1e-9)result.studHeightDiagnostic=QStringLiteral("The Verified Stud Height correction was measured with a different Stud OD correction and was not applied.");else result.studHeight=heightCandidate;}
    if(reason)*reason=result.any()?(result.studHeightDiagnostic.isEmpty()?QStringLiteral("Compatible"):result.studHeightDiagnostic):(result.studHeightDiagnostic.isEmpty()?QStringLiteral("The selected profile has no compatible verified functional correction for this print orientation."):result.studHeightDiagnostic);return result;
}

const FitProfileCorrection* ManufacturingMeshService::compatibleCorrection(const FitProfile&profile,FitPrintedOrientation orientation,QString*reason)
{
    const auto corrections=compatibleCorrections(profile,orientation,reason);return corrections.femaleDiameter?corrections.femaleDiameter:(corrections.studDiameter?corrections.studDiameter:corrections.studHeight);
}

FitPrintedOrientation ManufacturingMeshService::transformedOrientation(const FunctionalFeature&feature,const PrintOrientation&printOrientation)
{
    const auto axis=printOrientation.map(feature.frame.axis);const double z=std::abs(axis.z);
    if(z>=1.0-1e-6)return FitPrintedOrientation::FeatureAxisPerpendicularToBuildPlate;
    if(z<=1e-6)return FitPrintedOrientation::FeatureAxisParallelToBuildPlate;
    return FitPrintedOrientation::Unknown;
}

bool ManufacturingMeshService::hasApplicableCorrection(const FitProfile&profile,const LDrawSemanticOperandBuilder::Result&semantic,const PrintOrientation&printOrientation,QString*reason)
{
    if(!semantic.ok()){if(reason)*reason=semantic.diagnostics.join(' ');return false;}
    for(const auto&operand:semantic.operands)for(const auto&feature:operand.functionalFeatures){QString featureReason;const auto corrections=compatibleCorrections(profile,transformedOrientation(feature,printOrientation),&featureReason);if(correctionApplies(feature,corrections)){if(reason)*reason=QStringLiteral("Compatible correction for feature %1 after Print Orientation %2.").arg(feature.stableIdentity,printOrientation.summary());return true;}}
    if(reason)*reason=QStringLiteral("No recognized functional operand has a compatible Verified correction after Print Orientation %1.").arg(printOrientation.summary());return false;
}

bool ManufacturingMeshService::hasApplicableCorrection(const FitProfile&profile,const LDrawGeometry::LDrawLoadResult&source,const PrintOrientation&printOrientation,QString*reason)
{
    return hasApplicableCorrection(profile,LDrawSemanticOperandBuilder::build(source),printOrientation,reason);
}

ManufacturingMeshResult ManufacturingMeshService::generate(const LDrawGeometry::LDrawLoadResult&source,const PreparedMesh&prepared,const FitProfile&profile,const PrintOrientation&printOrientation)const
{
    if(!source.ok()||prepared.mesh.faces.empty()||prepared.partReference.isEmpty())return fail(ManufacturingMeshError::InvalidInput,"Source and nominal PreparedMesh are required.");
    QString reason;if(!FitCalibrationLibrary::profileCompatibility(profile,&reason))return fail(ManufacturingMeshError::IncompatibleProfile,reason);
    auto semantic=m_builder?m_builder(source):LDrawSemanticOperandBuilder::build(source);if(!semantic.ok())return fail(ManufacturingMeshError::SemanticFailure,semantic.diagnostics.join(' '));
    QVector<SemanticOperand> operands=semantic.operands;std::stable_sort(operands.begin(),operands.end(),[](const auto&a,const auto&b){const int ao=order(a.role),bo=order(b.role);return ao==bo?operandIdentity(a)<operandIdentity(b):ao<bo;});
    bool replaced=false;int skipped=0;QStringList featureIdentities,semanticIdentities,contractIdentities,correctionIdentity,provenance;double nominalDiameter=0,diameterCorrection=0,manufacturingDiameter=0,nominalHeight=0,heightCorrection=0,manufacturingHeight=0;
    provenance<<QStringLiteral("Print Orientation: %1").arg(printOrientation.summary());
    for(auto&operand:operands){for(const auto&feature:operand.functionalFeatures){const auto transformedAxis=printOrientation.map(feature.frame.axis);const auto orientation=transformedOrientation(feature,printOrientation);QString featureReason;const auto corrections=compatibleCorrections(profile,orientation,&featureReason);const QString orientationEvidence=QStringLiteral("Part axis %1 -> build axis %2 (%3)").arg(axisName(feature.frame.axis),axisName(transformedAxis),orientationName(orientation));FunctionalOperandRegenerationResult regenerated;if(feature.family==FunctionalInterfaceFamily::RoundTechnicPassage&&feature.role==FunctionalInterfaceRole::Female&&corrections.femaleDiameter&&feature.evidenceContract==corrections.femaleDiameter->semanticContractVersion){regenerated=FunctionalOperandRegenerator::regenerate(feature,{corrections.femaleDiameter->valueMillimetres});if(!regenerated.ok())return fail(ManufacturingMeshError::RegenerationFailure,regenerated.diagnostic);diameterCorrection=corrections.femaleDiameter->valueMillimetres;nominalDiameter=regenerated.resultingGoverningRadiusMillimetres*2.0-diameterCorrection;manufacturingDiameter=regenerated.resultingGoverningRadiusMillimetres*2.0;semanticIdentities<<corrections.femaleDiameter->semanticContractVersion;contractIdentities<<corrections.femaleDiameter->correctionContractVersion;correctionIdentity<<QStringLiteral("%1=%2").arg(corrections.femaleDiameter->correctionContractVersion).arg(diameterCorrection,0,'g',17);provenance<<QStringLiteral("Feature %1 [%2]: diameter %3 mm + %4 mm = %5 mm").arg(feature.stableIdentity,orientationEvidence).arg(nominalDiameter,0,'f',3).arg(diameterCorrection,0,'f',3).arg(manufacturingDiameter,0,'f',3);}else if(feature.family==FunctionalInterfaceFamily::StandardStud&&feature.role==FunctionalInterfaceRole::Male&&(corrections.studDiameter||corrections.studHeight)&&((corrections.studDiameter&&feature.evidenceContract==corrections.studDiameter->semanticContractVersion)||(corrections.studHeight&&feature.evidenceContract==corrections.studHeight->semanticContractVersion))){MaleStudDimensionalCorrection requested;requested.diameterMillimetres=corrections.studDiameter?corrections.studDiameter->valueMillimetres:0;requested.heightMillimetres=corrections.studHeight?corrections.studHeight->valueMillimetres:0;regenerated=FunctionalOperandRegenerator::regenerateStud(feature,requested);if(!regenerated.ok())return fail(ManufacturingMeshError::RegenerationFailure,regenerated.diagnostic);diameterCorrection=requested.diameterMillimetres;heightCorrection=requested.heightMillimetres;nominalDiameter=regenerated.resultingGoverningRadiusMillimetres*2.0-diameterCorrection;manufacturingDiameter=regenerated.resultingGoverningRadiusMillimetres*2.0;nominalHeight=regenerated.resultingAxialExtentMillimetres-heightCorrection;manufacturingHeight=regenerated.resultingAxialExtentMillimetres;if(corrections.studDiameter){semanticIdentities<<corrections.studDiameter->semanticContractVersion;contractIdentities<<corrections.studDiameter->correctionContractVersion;correctionIdentity<<QStringLiteral("%1=%2").arg(corrections.studDiameter->correctionContractVersion).arg(diameterCorrection,0,'g',17);}if(corrections.studHeight){semanticIdentities<<corrections.studHeight->semanticContractVersion;contractIdentities<<corrections.studHeight->correctionContractVersion;correctionIdentity<<QStringLiteral("%1=%2").arg(corrections.studHeight->correctionContractVersion).arg(heightCorrection,0,'g',17);}provenance<<QStringLiteral("Feature %1 [%2]: stud OD %3 mm + %4 mm = %5 mm; height %6 mm + %7 mm = %8 mm").arg(feature.stableIdentity,orientationEvidence).arg(nominalDiameter,0,'f',3).arg(diameterCorrection,0,'f',3).arg(manufacturingDiameter,0,'f',3).arg(nominalHeight,0,'f',3).arg(heightCorrection,0,'f',3);if(!corrections.studHeightDiagnostic.isEmpty())provenance<<corrections.studHeightDiagnostic;}else if(feature.family==FunctionalInterfaceFamily::StudReceivingClutch&&feature.role==FunctionalInterfaceRole::Female&&corrections.receivingTubeDiameter&&feature.evidenceContract==corrections.receivingTubeDiameter->semanticContractVersion){regenerated=FunctionalOperandRegenerator::regenerateReceivingTube(feature,{corrections.receivingTubeDiameter->valueMillimetres});if(!regenerated.ok())return fail(ManufacturingMeshError::RegenerationFailure,regenerated.diagnostic);diameterCorrection=corrections.receivingTubeDiameter->valueMillimetres;nominalDiameter=regenerated.resultingGoverningRadiusMillimetres*2.0-diameterCorrection;manufacturingDiameter=regenerated.resultingGoverningRadiusMillimetres*2.0;semanticIdentities<<corrections.receivingTubeDiameter->semanticContractVersion;contractIdentities<<corrections.receivingTubeDiameter->correctionContractVersion;correctionIdentity<<QStringLiteral("%1=%2").arg(corrections.receivingTubeDiameter->correctionContractVersion).arg(diameterCorrection,0,'g',17);provenance<<QStringLiteral("Feature %1 [%2]: receiving tube OD %3 mm + %4 mm = %5 mm; protected bore %6 mm").arg(feature.stableIdentity,orientationEvidence).arg(nominalDiameter,0,'f',3).arg(diameterCorrection,0,'f',3).arg(manufacturingDiameter,0,'f',3).arg(feature.protectedInnerRadiusMillimetres*2.0,0,'f',3);}if(regenerated.ok()){operand.closedMesh=regenerated.mesh;operand.analysis=regenerated.analysis;featureIdentities<<feature.stableIdentity;replaced=true;break;}++skipped;provenance<<QStringLiteral("Feature %1 [%2] remained nominal: %3").arg(feature.stableIdentity,orientationEvidence,featureReason);}}
    if(!replaced)return fail(ManufacturingMeshError::MissingCorrection,provenance.isEmpty()?QStringLiteral("No recognized functional operand matches the compatible profile corrections."):provenance.join(' '));
    auto backend=m_factory();if(!backend||operands.isEmpty())return fail(ManufacturingMeshError::BooleanFailure,"No Boolean composition service is available.");PrintMesh accumulated=operands.front().closedMesh;for(int i=1;i<operands.size();++i){auto operation=operands[i].role==SemanticRole::SubtractivePassage?backend->subtract(accumulated,operands[i].closedMesh):backend->unite(accumulated,operands[i].closedMesh);if(!operation.ok())return fail(ManufacturingMeshError::BooleanFailure,QString::fromStdString(operation.message));accumulated=std::move(operation.mesh);}
    const auto analysis=analyzeSource(accumulated);if(!validatePreparedMesh(analysis).ok())return fail(ManufacturingMeshError::InvalidResult,"The composed ManufacturingMesh failed strict validation.");
    semanticIdentities.removeDuplicates();contractIdentities.removeDuplicates();correctionIdentity.removeDuplicates();
    auto output=std::make_shared<ManufacturingMesh>();output->mesh=std::move(accumulated);output->analysis=analysis;output->partReference=prepared.partReference;output->fitProfileIdentity=profile.profileIdentity;output->sourceSessionIdentity=profile.sourceSessionIdentity;output->featureIdentities=featureIdentities;output->featureIdentity=featureIdentities.join('|');output->semanticContractVersion=semanticIdentities.join('|');output->correctionContractVersion=contractIdentities.join('|');output->regeneratorAlgorithmVersion=FitCalibrationLibrary::currentRegeneratorAlgorithmVersion();output->booleanVersion=backend->versionIdentity();output->nominalDiameterMillimetres=nominalDiameter;output->diameterCorrectionMillimetres=diameterCorrection;output->manufacturingDiameterMillimetres=manufacturingDiameter;output->nominalHeightMillimetres=nominalHeight;output->heightCorrectionMillimetres=heightCorrection;output->manufacturingHeightMillimetres=manufacturingHeight;
    output->nominalPreparationIdentity=prepared.partReference+'|'+prepared.ldrawIdentity+'|'+prepared.preparationProfileVersion+'|'+prepared.mcutVersion;output->provenance<<QStringLiteral("Nominal PreparedMesh: %1").arg(output->nominalPreparationIdentity)<<QStringLiteral("Verified Fit Profile: %1").arg(profile.profileIdentity)<<provenance;
    const QByteArray identity=(output->nominalPreparationIdentity+'|'+profile.profileIdentity+'|'+profile.processFingerprint+'|'+printOrientation.summary()+'|'+featureIdentities.join('|')+'|'+correctionIdentity.join('|')+'|'+output->regeneratorAlgorithmVersion+'|'+output->booleanVersion).toUtf8();output->identity=QString::fromLatin1(QCryptographicHash::hash(identity,QCryptographicHash::Sha256).toHex());
    ManufacturingMeshResult result;result.error=ManufacturingMeshError::None;result.manufacturingMesh=output;result.diagnostic=QStringLiteral("Separate profile-driven ManufacturingMesh generated per functional operand; %1 feature(s) corrected and %2 recognized feature(s) left nominal. Source and nominal PreparedMesh were not modified.").arg(featureIdentities.size()).arg(skipped);return result;
}

ManufacturingMeshResult ManufacturingMeshService::generate(const LDrawGeometry::LDrawLoadResult&source,const PreparedMesh&prepared,const FitProfile&profile,FitPrintedOrientation orientation)const
{
    PrintOrientation printOrientation;if(orientation==FitPrintedOrientation::FeatureAxisParallelToBuildPlate)printOrientation.rotate(PrintOrientation::Rotation::XPositive);return generate(source,prepared,profile,printOrientation);
}
}
